let workspaceInvites=[];
function workspaceDropdown(){return '<div class="workspace-control"><label for="globalWorkspace">Workspace</label><select id="globalWorkspace" onchange="switchWorkspace(Number(this.value))">'+spaces.map(w=>'<option value="'+w.id+'" '+(w.id===workspace?'selected':'')+'>'+esc(w.name)+'</option>').join('')+'</select><button class="text-link" onclick="openCreate(\'workspace\')">+ Create workspace</button></div>'}
const renderWorkflow=render;
render=function(){renderWorkflow();const switcher=$('.switcher');if(switcher)switcher.outerHTML=workspaceDropdown()};
switchWorkspace=function(id){captureReq();workspace=id;selected=projects.find(p=>p.space===id)?.id||0;filter='';render()};
function peopleFields(all=false){const list=all?[...new Map(users.map(u=>[u.email,u])).values()]:users.filter(u=>u.space===workspace);return '<fieldset class="people-picker"><legend>Assign existing users</legend>'+list.map(u=>'<label><input type="checkbox" name="member" value="'+u.id+'">'+avatar(u.name)+'<span>'+esc(u.name)+'<small>'+esc(u.email)+'</small></span></label>').join('')+'</fieldset><label class="field">Add unregistered people by email<textarea class="short-text" name="inviteEmails" placeholder="alex@example.com, maya@example.com"></textarea><small>Separate emails with commas or new lines. Pending invitations are simulated; no email is sent.</small></label><label class="field">Role for new members<select name="memberRole">'+roles.filter(r=>r!=='Owner').map(r=>'<option '+(r==='Editor'?'selected':'')+'>'+esc(r)+'</option>').join('')+'</select></label>'}
const createOriginal=openCreate;
openCreate=function(type){if(!['workspace','team'].includes(type))return createOriginal(type);let body=field(type==='workspace'?'Workspace name':'Team name','name')+field('Description','desc')+(type==='team'?'<p class="context-label">Workspace: <b>'+esc(spaces[workspace].name)+'</b></p>':'')+peopleFields(type==='workspace');if(type==='workspace')body+='<fieldset class="people-picker"><legend>Add teams</legend><p class="sub">Copy selected teams and their members into the new workspace.</p>'+teams.filter(t=>t.space===workspace).map(t=>'<label><input type="checkbox" name="team" value="'+t.id+'"><span>'+esc(t.name)+'<small>'+t.members.length+' members</small></span></label>').join('')+'</fieldset><label class="field">Create a new team (optional)<input name="newTeam" placeholder="e.g. Product discovery"><small>Selected users and pending invitees will join this team.</small></label>';modal('Create '+type,body,"saveWorkspaceOrTeam(event,'"+type+"')")};
function ensureMember(user,space,role){let existing=users.find(u=>u.email.toLowerCase()===user.email.toLowerCase()&&u.space===space);if(existing)return existing.id;const copy={...user,id:Math.max(0,...users.map(u=>u.id))+1,space,role:user.id===1?'Owner':role};users.push(copy);return copy.id}
function parseInvites(s){return [...new Set(s.split(/[,;\n]+/).map(x=>x.trim().toLowerCase()).filter(Boolean))]}
function saveWorkspaceOrTeam(e,type){e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim(),desc=String(f.get('desc')||'').trim(),role=String(f.get('memberRole')||'Editor'),emails=parseInvites(String(f.get('inviteEmails')||''));if(!name)return toast('Enter a name.');if(emails.some(email=>! /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)))return toast('Check the email addresses before saving.');if(type==='workspace'&&spaces.some(w=>w.name.toLowerCase()===name.toLowerCase()))return toast('A workspace with this name already exists.');if(type==='team'&&teams.some(t=>t.space===workspace&&t.name.toLowerCase()===name.toLowerCase()))return toast('A team with this name already exists in this workspace.');const target=type==='workspace'?spaces.length:workspace;if(type==='workspace')spaces.push({id:target,name,desc});let members=f.getAll('member').map(Number).map(id=>users.find(u=>u.id===id)).filter(Boolean).map(u=>ensureMember(u,target,role));if(type==='workspace')ensureMember(users.find(u=>u.id===1),target,'Owner');emails.forEach(email=>{let known=users.find(u=>u.email.toLowerCase()===email);if(known)members.push(ensureMember(known,target,role));else{const id=ensureMember({name:email.split('@')[0],email,status:'Pending invitation'},target,role);members.push(id);workspaceInvites.push({email,space:target,status:'Pending invitation'})}});members=[...new Set(members)];const nextTeamId=()=>Math.max(0,...teams.map(t=>t.id))+1;if(type==='team')teams.push({id:nextTeamId(),name,desc,space:target,members});else{f.getAll('team').map(Number).forEach(id=>{const t=teams.find(t=>t.id===id);if(t)teams.push({...t,id:nextTeamId(),space:target,members:t.members.map(uid=>ensureMember(users.find(u=>u.id===uid),target,role))})});const newTeam=String(f.get('newTeam')||'').trim();if(newTeam)teams.push({id:nextTeamId(),name:newTeam,desc:'Created with workspace',space:target,members});workspace=target;selected=0}$('#modal').close();navigate(type==='workspace'?'workspaces':'teams');toast(type==='workspace'?'Workspace created with assigned people and teams.':'Team created with selected members. No invitations were emailed.')}
const oldUserScreen=userScreen;
userScreen=function(){return oldUserScreen().replaceAll('>Suspend</button>','>Suspend</button>')+'<p class="sub">Pending invitation means an unregistered person was added to this prototype. No invitation email has been sent.</p>'};
toggleUser=function(id){const u=users.find(u=>u.id===id);if(u.status==='Pending invitation')return toast('This person must register through a connected invitation service.');u.status=u.status==='Active'?'Suspended':'Active';render()};
const captureWorkflow=captureReq;
captureReq=function(){const r=reqs[selected],p=plans[selected],a=architectures[selected];const before=r?JSON.stringify([r.brief,r.meeting,r.answers,r.doc]):null;const pn=p?.notes,ad=a?.doc;captureWorkflow();if(r&&!r.approved&&before!==JSON.stringify([r.brief,r.meeting,r.answers,r.doc]))r.reviewed=false;if(p&&!p.approved&&p.notes!==pn)p.reviewed=false;if(a&&!a.approved&&a.doc!==ad)a.reviewed=false};
render();
